// DST-safe stepping for scale columns, shared by the timeline column walk and by
// the ignore probe walk (DSUP-10817, GS-1312).
//
// A column walk has to step by the WALL CLOCK, not by elapsed time: a fall-back
// week is 169 elapsed hours long, so an elapsed two-hour step fits 85 columns
// into it instead of 84 and moves every column after the fold onto an odd wall
// hour - which is the extra 23:00-00:00 slot from the ticket.
//
// Minute and hour columns use local setters so every configured step advances the
// wall clock. Other units retain gantt's `_correct_dst_change` fallback rule.

var SECONDS_IN_UNIT = {
	second: 1,
	minute: 60,
	hour: 60 * 60,
	day: 60 * 60 * 24,
	week: 60 * 60 * 24 * 7,
	month: 60 * 60 * 24 * 30,
	quarter: 60 * 60 * 24 * 90,
	year: 60 * 60 * 24 * 365
};

/** Floor the sub-hour fields of a date (gantt `date.hour_start`/`minute_start`
 *  parity, including its guards). Writing a field is a WALL-CLOCK round-trip:
 *  at a daylight-saving fall-back fold an ambiguous wall time resolves to the
 *  EARLIER of its two instants, so rewriting an already-floored date there
 *  silently moves it back an hour and stalls the column walk (DSUP-10817,
 *  GS-1312). Guarding each write keeps an aligned date untouched. */
function floorTimeFields(date, floorMinutes) {
	var result = new Date(date);
	if (floorMinutes && result.getMinutes()) {
		result.setMinutes(0);
	}
	if (result.getSeconds()) {
		result.setSeconds(0);
	}
	if (result.getMilliseconds()) {
		result.setMilliseconds(0);
	}
	return result;
}

/** Wrap scheduler.date for the walk below. Units without a <unit>_start helper
 *  snap via the synthesized minute/hour starts, or pass through unchanged.
 *
 *  Note that `scheduler.date.hour_start`/`minute_start` are synthesized HERE and
 *  never defined on `scheduler.date` itself on purpose: both the legacy view name
 *  helper and `_set_timeline_dates` branch on the presence of
 *  `scheduler.date[unit + "_start"]`, so defining a real one would silently move
 *  the start of the visible range from the day start to the hour start. */
export function createSchedulerDateAdapter(dateHelper) {
	return {
		add: function(date, inc, unit) {
			return dateHelper.add(date, inc, unit);
		},
		unitStart: function(unit, date) {
			var helper = dateHelper[unit + "_start"];
			if (typeof helper === "function") {
				return helper.call(dateHelper, new Date(date));
			}
			// scheduler.date has no hour/minute starts - synthesize them
			if (unit === "hour") {
				return floorTimeFields(date, true);
			}
			if (unit === "minute") {
				return floorTimeFields(date, false);
			}
			return new Date(date);
		}
	};
}

/** DST correction fallback (gantt `_correct_dst_change` parity) for units not
 * handled by `wallClockAdd`: steps longer than an hour but shorter than a day are
 * shifted back by the timezone-offset delta. */
export function correctDstDefault(date, prevTimezoneOffset, step, unit, dateAdapter) {
	var timeUnit = (SECONDS_IN_UNIT[unit] || 0) * step;
	if (timeUnit > 60 * 60 && timeUnit < 60 * 60 * 24) {
		var offsetChanged = date.getTimezoneOffset() - prevTimezoneOffset;
		if (offsetChanged) {
			return dateAdapter.add(date, offsetChanged, "minute");
		}
	}
	return date;
}

function wallClockAdd(date, step, unit) {
	var result = new Date(date);
	if (unit === "minute") {
		result.setMinutes(result.getMinutes() + step);
		return result;
	}
	if (unit === "hour") {
		result.setHours(result.getHours() + step);
		return result;
	}
	return null;
}

/**
 * Move a column cursor one step forward: elapsed `add`, DST correction, then the
 * adapter's unit-start snap.
 *
 * Returns `null` when the cursor cannot be advanced at all, so every caller ends
 * its walk instead of looping. Both post-`add` corrections are wall-clock
 * operations and can land on or behind the column they came from - an ambiguous
 * wall time at a fall-back fold, a DST shift that happens to equal the step (a
 * 2 h shift at a 2 h step, e.g. Antarctica/Troll), a non-positive step, or a
 * custom `<unit>_start` helper. Those cases degrade to the uncorrected elapsed
 * step: a view may end up with a wrong column boundary, never with a hung tab.
 *
 * The snap is deliberately not a caller option: it is what re-aligns hour columns
 * after a fractional-offset DST change (Australia/Lord_Howe moves the clock by 30
 * minutes), and a caller that skipped it would drift for the rest of the range.
 * The timeline column walk and the ignore probe walk both step through here so
 * that they agree column for column - the probe reports by column INDEX.
 */
export function advanceColumnCursor(curr, step, unit, dateAdapter) {
	if (!Number.isFinite(step) || step === 0) {
		return null;
	}

	// A backwards move is defined as the inverse of a successful forward
	// boundary.  Re-running the forward operation from the raw predecessor is
	// important at a fall-back fold, where constructing an ambiguous local date
	// directly may choose the wrong occurrence.
	if (step < 0) {
		var rawPrevious = wallClockAdd(curr, step, unit) || dateAdapter.add(curr, step, unit);
		var previous = dateAdapter.unitStart(unit, new Date(rawPrevious));
		var roundTrip = advanceColumnCursor(previous, -step, unit, dateAdapter);
		if (roundTrip && +roundTrip === +curr && +previous < +curr) {
			return previous;
		}
		return +rawPrevious < +curr ? new Date(rawPrevious) : null;
	}

	var tzOffset = curr.getTimezoneOffset();
	var wallStepped = wallClockAdd(curr, step, unit);
	var stepped = wallStepped || dateAdapter.add(curr, step, unit);

	var next = wallStepped || correctDstDefault(stepped, tzOffset, step, unit, dateAdapter);
	next = dateAdapter.unitStart(unit, next);

	if (+next > +curr) {
		return next;
	}
	return +stepped > +curr ? stepped : null;
}

export function validateColumnRange(count, step, length) {
	if (!Number.isFinite(step) || step <= 0) {
		throw new Error("Timeline x_step must be a positive finite number");
	}
	if (!Number.isFinite(count) || count <= 0 || Math.floor(count) !== count) {
		throw new Error("Timeline x_size must be a positive finite integer");
	}
	if (length !== undefined && length !== null &&
		(!Number.isFinite(length) || length <= 0 || Math.floor(length) !== length)) {
		throw new Error("Timeline x_length must be a positive finite integer");
	}
}

/** Return every boundary, including the start, and the exclusive end. */
export function walkColumnBoundaries(start, count, step, unit, dateAdapter) {
	validateColumnRange(count, step);
	var boundaries = [new Date(start)];
	var cursor = new Date(start);
	for (var i = 0; i < count; i++) {
		var next = advanceColumnCursor(cursor, step, unit, dateAdapter);
		if (!next || +next <= +cursor) {
			throw new Error("Unable to produce timeline boundary " + (i + 1) + " for " + unit + " step " + step);
		}
		boundaries.push(new Date(next));
		cursor = next;
	}
	return { boundaries: boundaries, end: new Date(cursor) };
}

/**
 * Exclusive end of a range that holds exactly `count` columns starting at
 * `start` - the boundary `count` steps away, walked with `advanceColumnCursor`.
 *
 * A range end computed as elapsed time (`start + count x step` hours) does NOT
 * agree with a wall-clock column walk across a DST transition: a fall-back day is
 * one hour longer than its wall clock says, so the elapsed end leaves room for
 * one column too many, and a spring-forward day one too few. Deriving the end
 * from the same walk that emits the columns keeps every range at its configured
 * column count on a transition day (DSUP-10817).
 */
export function columnRangeEnd(start, count, step, unit, dateAdapter) {
	return walkColumnBoundaries(start, count, step, unit, dateAdapter).end;
}
